const {test,expect}=require('@playwright/test');
test.use({viewport:{width:390,height:844},isMobile:true,hasTouch:true,reducedMotion:'reduce'});
const KEY='firemate_arcade_restaurant_v2';
const seed={coins:500,served:7,level:3,stoves:[null,null,null],decor:4,custom:{preserve:'future-field'}};
async function load(page,state=seed){await page.addInitScript(({key,state})=>{if(!localStorage.getItem(key))localStorage.setItem(key,JSON.stringify(state));localStorage.setItem('restaurant-finance-sentinel','preserve')},{key:KEY,state});await page.goto('/arcade/restaurant.html');await expect(page.locator('#restaurantRoom [data-room-stove]')).toHaveCount(state.stoves.length)}
const read=page=>page.evaluate(key=>JSON.parse(localStorage.getItem(key)),KEY);
test('restaurant quarter-view stoves preserve jobs, update real time, cook and sell without changing other records',async({browser})=>{
 test.setTimeout(60000);
 for(const width of [320,390,430]){
 const context=await browser.newContext({viewport:{width,height:844},isMobile:true,hasTouch:true,reducedMotion:'reduce'});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.clock.install();const now=await page.evaluate(()=>Date.now());const state={...seed,stoves:[{recipe:0,ends:now+2000},null,null]};await load(page,state);
 expect(await read(page)).toEqual(state);await expect(page.locator('#restaurantRoom .room-cell')).toHaveCount(64);await expect(page.locator('[data-room-stove="0"]')).toHaveAttribute('aria-label',/조리 중/);
 await page.clock.fastForward(3000);await expect(page.locator('[data-room-stove="0"]')).toHaveAttribute('aria-label',/완성/);await page.locator('[data-room-stove="0"]').click();const transferred=await read(page);expect(transferred.coins).toBe(500);expect(transferred.served).toBe(7);expect(transferred.stoves).toEqual([null,null,null]);expect(transferred.service.stock[0].batches[0]).toMatchObject({source:{recipe:0,value:12},total:4,remaining:4,price:3});await page.clock.runFor(14500);const partial=await read(page);expect(partial.coins).toBeGreaterThan(500);expect(partial.coins).toBeLessThan(512);expect(partial.growth.xp).toBe((partial.coins-500)/3);await page.clock.runFor(45000);expect((await read(page)).coins).toBe(512);expect((await read(page)).served).toBe(11);
 await page.locator('[data-room-stove="1"]').click();await expect(page.locator('#recipeDialog')).toBeVisible();await page.locator('#recipeDialog').getByRole('button',{name:/주먹밥/}).click();await expect(page.locator('#recipeDialog')).toBeHidden();const started=await read(page);expect(started.coins).toBe(509);expect(started.stoves[1].recipe).toBe(0);expect(started.stoves[1].ends).toBeGreaterThan(now+60000);expect(started.custom).toEqual(state.custom);
 await page.reload();expect((await read(page)).stoves[1]).toEqual(started.stoves[1]);await page.clock.fastForward(61000);await expect(page.locator('[data-room-stove="1"]')).toHaveAttribute('aria-label',/완성/);expect(await page.evaluate(()=>localStorage.getItem('restaurant-finance-sentinel'))).toBe('preserve');expect(await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth)).toBeLessThanOrEqual(1);expect(errors).toEqual([]);await context.close();
 }
});
test('restaurant furniture edit validates space, cancels, persists additively and rolls back real quota failure',async({page})=>{
 await load(page);const before=await read(page),original=await page.locator('[data-room-item="table-0"]').getAttribute('transform');
 const move=async(id,cell)=>{if(await page.locator('[data-room-item="'+id+'"]').getAttribute('aria-pressed')!=='true')await page.locator('[data-room-item="'+id+'"] .room-action').click();const target=page.locator('[data-room-target="'+cell+'"]');await (await target.count()?target:page.locator('[data-room-cell="'+cell+'"]')).click()};
 await page.locator('#roomEdit').click();await move('table-0','6,0');await expect(page.locator('#status')).toContainText('출입구');expect(await page.locator('[data-room-item="table-0"]').getAttribute('transform')).toBe(original);await move('table-0','7,7');expect(await read(page)).toEqual(before);await page.locator('#roomEditCancel').click();await expect(page.locator('#roomEditBar')).toBeHidden();expect(await page.locator('[data-room-item="table-0"]').getAttribute('transform')).toBe(original);expect(await read(page)).toEqual(before);
 await page.locator('#roomEdit').click();await move('table-0','7,7');await page.locator('#roomEditSave').click();await expect(page.locator('#roomEditBar')).toBeHidden();const saved=await read(page);expect(saved.roomLayout.positions['table-0']).toEqual({x:7,y:7});const {roomLayout,...other}=saved;expect(other).toEqual(before);await page.reload();expect((await read(page)).roomLayout).toEqual(saved.roomLayout);
 await page.locator('#roomEdit').click();await move('chair-0','0,7');await page.evaluate(()=>{window.originalRestaurantSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k==='firemate_arcade_restaurant_v2')throw new DOMException('Quota exceeded','QuotaExceededError');return window.originalRestaurantSet.call(this,k,v)}});await page.locator('#roomEditSave').click();await expect(page.locator('#status')).toContainText('저장하지 못');await expect(page.locator('#roomEditBar')).toBeVisible();expect(await read(page)).toEqual(saved);await page.evaluate(()=>Storage.prototype.setItem=window.originalRestaurantSet);await page.goBack();await expect(page.locator('#roomEditBar')).toBeHidden();expect(await read(page)).toEqual(saved);
});
test('restaurant legacy and unknown records survive, and modal/back/offline navigation preserves financial data',async({browser})=>{
 test.setTimeout(60000);
 const legacyContext=await browser.newContext({reducedMotion:'reduce'});await legacyContext.addInitScript(()=>localStorage.setItem('firemate_arcade_restaurant_v1',JSON.stringify({coins:99,served:4,level:2})));const legacyPage=await legacyContext.newPage();await legacyPage.goto('/arcade/restaurant.html');const migrated=await read(legacyPage);expect(migrated.coins).toBe(249);expect(migrated.served).toBe(4);await legacyPage.reload();expect(await read(legacyPage)).toEqual(migrated);expect(await legacyPage.evaluate(()=>JSON.parse(localStorage.getItem('firemate_arcade_restaurant_v1')))).toEqual({coins:99,served:4,level:2});await legacyContext.close();
 const unknownContext=await browser.newContext({reducedMotion:'reduce'});const unknownPage=await unknownContext.newPage();const future={...seed,roomLayout:{version:99,positions:{future:{x:1,y:1}}},stoves:[{recipe:99,ends:1893456000000},null]};await load(unknownPage,future);await unknownPage.locator('#roomEdit').click();await expect(unknownPage.locator('#status')).toContainText('저장 배치');expect(await read(unknownPage)).toEqual(future);await unknownPage.locator('[data-room-stove="0"]').click();await expect(unknownPage.locator('#status')).toContainText('알 수 없는 요리 기록');expect(await read(unknownPage)).toEqual(future);await unknownContext.close();
 const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,reducedMotion:'reduce'});await context.route('https://api.frankfurter.dev/**',r=>r.abort());const page=await context.newPage();await page.goto('/index.html');await page.waitForFunction(()=>!!navigator.serviceWorker.controller);const financial=await page.evaluate(()=>localStorage.getItem('firemate_smart_v3'));await page.goto('/arcade/index.html');await page.locator('a[href="./restaurant.html"],a[href="restaurant.html"]').click();await expect(page.locator('#restaurantRoom')).toBeVisible();await page.locator('#openKitchen').click();await page.locator('#kitchen [data-slot="0"]').click();await expect(page.locator('#recipeDialog')).toBeVisible();await page.goBack();await expect(page.locator('#recipeDialog')).toBeHidden();await expect(page.locator('#kitchenDialog')).toBeVisible();await page.goBack();await expect(page.locator('#kitchenDialog')).toBeHidden();await page.locator('#roomEdit').click();await page.goBack();await expect(page.locator('#roomEditBar')).toBeHidden();
 const saved=await read(page);await context.setOffline(true);await page.reload();await expect(page.locator('#restaurantRoom [data-room-stove]')).toHaveCount(saved.stoves.length);expect(await read(page)).toEqual(saved);expect(await page.evaluate(()=>localStorage.getItem('firemate_smart_v3'))).toBe(financial);await page.goBack();await expect(page).toHaveURL(/arcade\/index.html/);expect(await page.evaluate(()=>localStorage.getItem('firemate_smart_v3'))).toBe(financial);await context.close();
});

