test('restaurant fullscreen rejection and unavailable orientation lock retain a playable saved game',async({page})=>{
 await load(page);const initial=await read(page);await page.evaluate(()=>{document.documentElement.requestFullscreen=async()=>{throw new DOMException('Denied','NotAllowedError')}});await page.locator('#restaurantFullscreen').tap();await expect(page.locator('#orientationHint')).toContainText('열지 못');expect(await read(page)).toEqual(initial);
 await page.evaluate(()=>{window.restaurantScreenCalls=[];document.documentElement.requestFullscreen=async()=>{window.restaurantScreenCalls.push('enter');Object.defineProperty(document,'fullscreenElement',{configurable:true,get:()=>document.documentElement});document.dispatchEvent(new Event('fullscreenchange'))};screen.orientation.lock=async mode=>{window.restaurantScreenCalls.push(mode);throw new DOMException('Unsupported','NotSupportedError')};screen.orientation.unlock=()=>window.restaurantScreenCalls.push('unlock');document.exitFullscreen=async()=>{window.restaurantScreenCalls.push('exit');Object.defineProperty(document,'fullscreenElement',{configurable:true,get:()=>null});document.dispatchEvent(new Event('fullscreenchange'))}});
 await page.locator('#restaurantFullscreen').tap();await expect(page.locator('#restaurantFullscreen')).toHaveAttribute('aria-pressed','true');await expect(page.locator('#orientationHint')).toContainText('가로로 돌려');await page.locator('#restaurantFullscreen').tap();await expect(page.locator('#restaurantFullscreen')).toHaveAttribute('aria-pressed','false');expect(await page.evaluate(()=>window.restaurantScreenCalls)).toEqual(['enter','landscape','exit','unlock']);expect(await read(page)).toEqual(initial);
});

