test('restaurant all five plate balances conserve total rewards through delivery, reload and sale',async({browser})=>{
 test.setTimeout(90000);for(const [recipe,count,price,total] of [[0,4,3,12],[1,5,7,35],[2,10,11,110],[3,10,25,250],[4,12,65,780]]){
 const context=await browser.newContext({viewport:{width:844,height:390},isMobile:true,hasTouch:true,reducedMotion:'reduce'});const page=await context.newPage();await page.clock.install();await load(page,{...seed,level:5,stoves:[{recipe,ends:0},null,null]});await page.locator('[data-room-stove="0"]').tap();const inv=await page.evaluate(()=>restaurantRoomBridge.inventory()[0]);expect(inv).toMatchObject({remaining:count,price,value:total});await page.clock.runFor(4500);let s=await read(page);const owed=(await page.evaluate(()=>restaurantRoomBridge.inventory())).reduce((sum,x)=>sum+(x?.value||0),0)+s.service.guests.filter(g=>g?.batch&&!g.paid).reduce((sum,g)=>sum+g.batch.value,0);expect(s.coins-500+owed).toBe(total);expect(s.service.stock[0].batches[0].remaining).toBe(count-1);await page.locator('[data-room-item="counter-0"]').tap();await expect(page.locator('#counterStockDetails')).toContainText('접시당 '+price+'코인');await expect(page.locator('#counterStockDetails')).toContainText('전달·식사 중 '+price+'코인 · 재고에서 제외');await page.goBack();await expect(page.locator('#counterDialog')).toBeHidden();await page.reload();await page.clock.runFor(count*15000);s=await read(page);expect(s.coins).toBe(500+total);expect(s.served).toBe(7+count);expect(s.growth.xp).toBe(count);expect(s.level).toBe(5);expect(s.service.stock).toEqual([null,null]);await page.reload();await page.clock.runFor(20000);expect((await read(page)).coins).toBe(500+total);expect((await read(page)).growth.xp).toBe(count);await context.close();}
});

