 const futureContext=await browser.newContext({reducedMotion:'reduce'});const futurePage=await futureContext.newPage();const future={...seed,growth:{version:99,xp:100,extra:'preserve'},stoves:[{recipe:0,ends:0},null,null]};await load(futurePage,future);await futurePage.locator('[data-room-stove="0"]').tap();expect(await read(futurePage)).toEqual(future);await expect(futurePage.locator('#chefLevel')).toContainText('기록 확인');await futureContext.close();
