// Long ledger tests above use reduced motion. These explicitly exercise normal frame interpolation.
test('restaurant normal-motion service preserves actors across refill, walks only free cells and hands off distinct food',async({browser})=>{
 test.setTimeout(60000);const context=await browser.newContext({viewport:{width:932,height:430},isMobile:true,hasTouch:true,reducedMotion:'no-preference'}),page=await context.newPage();await page.clock.install();await load(page,{...seed,stoves:[{recipe:0,ends:0},{recipe:1,ends:0},{recipe:0,ends:0}]});await page.locator('[data-room-stove="0"]').tap();await page.locator('[data-room-stove="1"]').tap();await page.evaluate(()=>window.originalWaiter=document.querySelector('[data-actor="waiter-service"]'));
 let previous=null,refilled=false,sawCarry=false,sawMeal=false,sawBack=false,sawReturn=false;const occupied=new Set(['1,1','3,1','5,1','2,3','3,3','2,5','1,5','2,6','5,5','4,5','5,6','0,6','7,6','1,2']);
 for(let i=0;i<320;i++){
  await page.clock.runFor(50);if(i===80){await page.locator('[data-room-stove="2"]').tap();refilled=true;expect(await page.evaluate(()=>document.querySelector('[data-actor="waiter-service"]')===window.originalWaiter)).toBe(true)}
  const sample=await page.evaluate(()=>{const w=document.querySelector('[data-actor="waiter-service"]');return {x:+w.dataset.x,y:+w.dataset.y,pose:w.dataset.pose,back:w.dataset.view==='back',carry:!!document.querySelector('[data-actor^="carry-"] .room-food'),meal:!!document.querySelector('[data-actor^="meal-"] .room-food'),s:restaurantRoomBridge.snapshot(),stock:restaurantRoomBridge.inventory()}});
  expect(occupied.has(Math.floor(sample.x)+','+Math.floor(sample.y))).toBe(false);
  if(previous)expect(Math.hypot(sample.x-previous.x,sample.y-previous.y)).toBeLessThan(.8);
  if(previous&&sample.pose==='standing'&&Math.hypot(sample.x-previous.x,sample.y-previous.y)>.01)sawReturn=true;
  const owed=sample.stock.reduce((n,x)=>n+(x?.value||0),0)+sample.s.service.guests.filter(g=>g?.batch&&!g.paid).reduce((n,g)=>n+g.batch.value,0);expect(sample.s.coins+owed).toBe(500+12+35+(refilled?12:0));
  sawCarry||=sample.carry;sawMeal||=sample.meal;sawBack||=sample.back;previous=sample;
 }
 expect({sawCarry,sawMeal,sawBack,sawReturn}).toEqual({sawCarry:true,sawMeal:true,sawBack:true,sawReturn:true});expect(await page.locator('[data-actor]').count()).toBeLessThanOrEqual(5);expect((await read(page)).custom).toEqual(seed.custom);await context.close();
});

test('restaurant normal-motion pause and reduced-motion preference preserve timing and immediate cooking feedback',async({browser})=>{
 const context=await browser.newContext({viewport:{width:844,height:390},isMobile:true,hasTouch:true,reducedMotion:'no-preference'}),page=await context.newPage();await page.addInitScript(()=>{window.restaurantFrames=new Set();const request=window.requestAnimationFrame.bind(window),cancel=window.cancelAnimationFrame.bind(window);window.requestAnimationFrame=fn=>{let id;id=request(t=>{window.restaurantFrames.delete(id);fn(t)});window.restaurantFrames.add(id);return id};window.cancelAnimationFrame=id=>{window.restaurantFrames.delete(id);cancel(id)}});await page.clock.install();await load(page,{...seed,stoves:[{recipe:0,ends:0},null,null]});expect(await page.evaluate(()=>window.restaurantFrames.size)).toBe(0);await page.locator('[data-room-stove="0"]').tap();await page.clock.runFor(4000);await page.locator('#openKitchen').tap();const frozen=await read(page),pose=await page.locator('[data-actor="waiter-service"]').getAttribute('transform');expect(await page.evaluate(()=>window.restaurantFrames.size)).toBe(0);await page.clock.runFor(5000);expect(await read(page)).toEqual(frozen);expect(await page.locator('[data-actor="waiter-service"]').getAttribute('transform')).toBe(pose);await page.goBack();await expect(page.locator('#kitchenDialog')).toBeHidden();await page.clock.runFor(500);expect(await page.locator('[data-actor="waiter-service"]').getAttribute('transform')).not.toBe(pose);
 await page.emulateMedia({reducedMotion:'reduce'});expect(await page.evaluate(()=>window.restaurantFrames.size)).toBe(0);expect(await page.locator('.room-person-bob').first().evaluate(e=>getComputedStyle(e).animationName)).toBe('none');await page.locator('[data-room-stove="1"]').tap();await page.locator('#recipeDialog').getByRole('button',{name:/주먹밥/}).tap();await expect(page.locator('[data-room-stove="1"]')).toHaveClass(/cooking/);await page.locator('[data-room-stove="1"]').tap();await expect(page.locator('[data-room-stove="1"]')).toHaveClass(/room-touched/);await expect(page.locator('#status')).toContainText('조리 중');await page.clock.fastForward(61000);await expect(page.locator('[data-room-stove="1"]')).toHaveClass(/ready/);await expect(page.locator('[data-room-stove="1"] .room-food-0')).toBeVisible();expect((await read(page)).stoves[1].recipe).toBe(0);await context.close();
});

