test('restaurant normal-motion team keeps two carriers, pauses together and preserves the sale ledger',async({browser})=>{
 const context=await browser.newContext({viewport:{width:932,height:430},isMobile:true,hasTouch:true,reducedMotion:'no-preference'}),page=await context.newPage();await page.clock.install({time:new Date('2026-10-19T00:00:00Z')});await page.clock.pauseAt(new Date('2026-10-19T00:00:01Z'));await load(page,{...seed,staff:{version:1,servers:2,assignments:{},note:'keep'},stoves:[{recipe:0,ends:0},{recipe:1,ends:0},null]});await page.locator('[data-room-stove="0"]').tap();await page.locator('[data-room-stove="1"]').tap();await page.clock.runFor(3500);await expect(page.locator('[data-actor^="carry-"]')).toHaveCount(2);const initial=await page.locator('[data-actor^="waiter-service"]').evaluateAll(es=>es.map(e=>e.getAttribute('transform')));await page.clock.runFor(500);const moving=await page.locator('[data-actor^="waiter-service"]').evaluateAll(es=>es.map(e=>e.getAttribute('transform')));expect(moving[0]).not.toBe(initial[0]);expect(moving[1]).not.toBe(initial[1]);await page.locator('#openExpansion').tap();const paused=await read(page),pose=await page.locator('[data-actor^="waiter-service"]').evaluateAll(es=>es.map(e=>e.getAttribute('transform')));await page.clock.runFor(4000);expect(await read(page)).toEqual(paused);expect(await page.locator('[data-actor^="waiter-service"]').evaluateAll(es=>es.map(e=>e.getAttribute('transform')))).toEqual(pose);await page.goBack();await expect(page.locator('#expansionDialog')).toBeHidden();await page.clock.runFor(16000);const s=await read(page),stock=await page.evaluate(()=>restaurantRoomBridge.inventory());const owed=stock.reduce((n,x)=>n+(x?.value||0),0)+s.service.guests.filter(g=>g?.batch&&!g.paid).reduce((n,g)=>n+g.batch.value,0);expect(s.coins+owed).toBe(547);expect(s.staff.note).toBe('keep');expect(await page.locator('[data-actor]').count()).toBeLessThanOrEqual(8);await context.close();
});

// v1.8 decorative ownership uses the same save transaction as coins.
const openFurniture=async(page,tab='warehouse')=>{await page.locator('#openFurniture').click();await page.locator(tab==='shop'?'#showFurnitureShop':'#showFurnitureWarehouse').click()};
const closeFurniture=async page=>{await page.goBack();await expect(page.locator('#furnitureDialog')).toBeHidden();await page.waitForFunction(()=>!history.state?.restaurantDialog)};
async function placeOwned(page,id){await page.locator('[data-furniture-place="'+id+'"]').click();await expect(page.locator('#roomEditBar')).toBeVisible();const cell=page.locator('.room-placement.permitted').first();await expect(cell).toBeVisible();await cell.click();await page.locator('#roomEditSave').click();await expect(page.locator('#roomEditBar')).toBeHidden();await page.waitForFunction(()=>!history.state?.restaurantEditing)}
test('restaurant furniture ownership completes buy cancel place store reload retrieve sell with exact coins',async({page})=>{
 await load(page);await openFurniture(page,'shop');await page.locator('[data-furniture-buy="flower"]').click();let s=await read(page);expect(s.coins).toBe(450);expect(s.furniture).toEqual({version:1,nextId:2,items:[{id:'furn-1',sku:'flower',paid:50,location:'warehouse',position:null}]});
 await page.bringToFront();if(!await page.locator('#furnitureDialog').isVisible())await openFurniture(page,'warehouse');await page.locator('[data-furniture-place="furn-1"]').click();await expect(page.locator('#roomEditBar')).toBeVisible();await page.locator('#roomEditCancel').click();await expect(page.locator('#roomEditBar')).toBeHidden();expect(await read(page)).toEqual(s);await openFurniture(page);await placeOwned(page,'furn-1');s=await read(page);expect(s.furniture.items[0].location).toBe('placed');await expect(page.locator('[data-room-item="furn-1"][data-kind="flower"]')).toHaveCount(1);
 await openFurniture(page);await page.locator('[data-furniture-store="furn-1"]').click();s=await read(page);expect(s.furniture.items[0].location).toBe('warehouse');await closeFurniture(page);await expect(page.locator('[data-room-item="furn-1"]')).toHaveCount(0);await page.reload();expect(await read(page)).toEqual(s);await openFurniture(page);await placeOwned(page,'furn-1');await openFurniture(page);page.once('dialog',d=>{expect(d.message()).toContain('25코인');d.dismiss()});await page.locator('[data-furniture-sell="furn-1"]').click();expect((await read(page)).coins).toBe(450);page.once('dialog',d=>d.accept());await page.locator('[data-furniture-sell="furn-1"]').click();s=await read(page);expect(s.coins).toBe(475);expect(s.furniture.items[0].location).toBe('sold');await expect(page.locator('[data-owned-id]')).toHaveCount(0);await closeFurniture(page);await expect(page.locator('[data-room-item="furn-1"]')).toHaveCount(0);const{furniture,roomLayout,...rest}=s;expect(rest).toEqual({...seed,coins:475});await page.reload();expect(await read(page)).toEqual(s);expect(await page.evaluate(()=>localStorage.getItem('restaurant-finance-sentinel'))).toBe('preserve');
});
test('restaurant furniture quota failures roll back coins objects placement storage and sale, stale tabs cannot overwrite',async({browser})=>{
 const context=await browser.newContext({reducedMotion:'reduce'}),page=await context.newPage();await load(page);// Stale tab was loaded before the owner's transactions, retaining its original snapshot.await openFurniture(page,'shop');
 const fail=()=>page.evaluate(()=>{window.furnitureSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k==='firemate_arcade_restaurant_v2')throw new DOMException('quota','QuotaExceededError');return window.furnitureSet.call(this,k,v)}}),restore=()=>page.evaluate(()=>Storage.prototype.setItem=window.furnitureSet);
 await fail();await page.locator('[data-furniture-buy="leaf"]').click();expect(await read(page)).toEqual(seed);expect(await page.evaluate(()=>restaurantRoomBridge.snapshot())).toEqual(seed);await expect(page.locator('#furnitureFeedback')).toContainText('저장하지 못');await restore();await page.locator('[data-furniture-buy="leaf"]').dblclick();let saved=await read(page);expect(saved.coins).toBe(470);expect(saved.furniture.items).toHaveLength(1);
 const stale=await context.newPage();await stale.goto('/arcade/restaurant.html');await page.bringToFront();
 await page.locator('[data-furniture-place="furn-1"]').click();await expect(page.locator('#roomEditBar')).toBeVisible();await page.locator('.room-placement.permitted').first().click();await fail();await page.locator('#roomEditSave').click();expect(await read(page)).toEqual(saved);await expect(page.locator('#roomEditBar')).toBeVisible();await restore();await page.locator('#roomEditSave').click();await expect(page.locator('#roomEditBar')).toBeHidden();await page.waitForFunction(()=>!history.state?.restaurantEditing);saved=await read(page);
 await openFurniture(page);await fail();await page.locator('[data-furniture-store="furn-1"]').click();expect(await read(page)).toEqual(saved);page.once('dialog',d=>d.accept());await page.locator('[data-furniture-sell="furn-1"]').click();expect(await read(page)).toEqual(saved);await restore();await page.locator('[data-furniture-store="furn-1"]').click();saved=await read(page);
 await openFurniture(stale,'shop');await stale.locator('[data-furniture-buy="lamp"]').click();expect(await read(stale)).toEqual(saved);await expect(stale.locator('#furnitureFeedback')).toContainText('다른 창');
 page.once('dialog',d=>d.accept());await page.locator('[data-furniture-sell="furn-1"]').click();saved=await read(page);expect(saved.coins).toBe(485);expect(await page.evaluate(()=>restaurantRoomBridge.furnitureAction('sell','furn-1'))).toBe(false);expect(await read(page)).toEqual(saved);await context.close();
});
